rules.remediationScript:
Import-Module Microsoft.Graph.Identity.SignIns

# Vervang door de object-id's van de break-glass-groep (sectie 6.2: nooit zonder uitzondering).
$breakGlassGroupId = '<object-id-van-break-glass-security-group>'

$params = @{
    DisplayName = 'CA-BASE-001-MFAAllUsers'
    State       = 'enabledForReportingButNotEnforced'  # eerst report-only (buildplan sectie 6.2), pas na validatie op 'enabled'
    Conditions  = @{
        Users = @{
            IncludeUsers = @('All')
            ExcludeGroups = @($breakGlassGroupId)
        }
        Applications = @{ IncludeApplications = @('All') }
    }
    GrantControls = @{
        Operator = 'OR'
        BuiltInControls = @('mfa')
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

$params = @{
    DisplayName = 'CA-BASE-002-BlockLegacyAuth'
    State       = 'enabledForReportingButNotEnforced'  # eerst report-only, controleer sign-in-logs op legitiem legacy-verkeer
    Conditions  = @{
        Users = @{ IncludeUsers = @('All') }
        Applications = @{ IncludeApplications = @('All') }
        ClientAppTypes = @('exchangeActiveSync', 'other')
    }
    GrantControls = @{
        Operator = 'OR'
        BuiltInControls = @('block')
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

# Vervang door de app-id('s) van de gevoelige applicatie(s) voor deze klant.
$sensitiveAppIds = @('<application-id-1>')

$params = @{
    DisplayName = 'CA-BASE-003-DeviceComplianceSensitiveApps'
    State       = 'enabledForReportingButNotEnforced'
    Conditions  = @{
        Users = @{ IncludeUsers = @('All') }
        Applications = @{ IncludeApplications = $sensitiveAppIds }
    }
    GrantControls = @{
        Operator = 'OR'
        BuiltInControls = @('compliantDevice', 'domainJoinedDevice')
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

# Vereist Entra ID P2 — controleer eerst de licentie van deze klant.
$params = @{
    DisplayName = 'CA-BASE-004-SigninRiskPolicy'
    State       = 'enabledForReportingButNotEnforced'
    Conditions  = @{
        Users = @{ IncludeUsers = @('All') }
        Applications = @{ IncludeApplications = @('All') }
        SignInRiskLevels = @('high', 'medium')
    }
    GrantControls = @{
        Operator = 'OR'
        BuiltInControls = @('mfa')
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

# Vereist Entra ID P2 — controleer eerst de licentie van deze klant.
$params = @{
    DisplayName = 'CA-BASE-005-UserRiskPolicy'
    State       = 'enabledForReportingButNotEnforced'
    Conditions  = @{
        Users = @{ IncludeUsers = @('All') }
        Applications = @{ IncludeApplications = @('All') }
        UserRiskLevels = @('high')
    }
    GrantControls = @{
        Operator = 'AND'
        BuiltInControls = @('mfa', 'passwordChange')
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

# Stap 1: named location aanmaken met de bekende, vertrouwde IP-ranges van deze klant.
$namedLocation = @{
    '@odata.type' = '#microsoft.graph.ipNamedLocation'
    DisplayName   = 'Vertrouwde kantoorlocaties'
    IsTrusted     = $true
    IpRanges      = @(@{ '@odata.type' = '#microsoft.graph.iPv4CidrRange'; CidrAddress = '<klant-ip-range>/32' })
}
$location = New-MgIdentityConditionalAccessNamedLocation -BodyParameter $namedLocation

# Stap 2: CA-policy die toegang buiten deze locaties blokkeert (report-only eerst).
$params = @{
    DisplayName = 'CA-BASE-006-LocationRestriction'
    State       = 'enabledForReportingButNotEnforced'
    Conditions  = @{
        Users = @{ IncludeUsers = @('All') }
        Applications = @{ IncludeApplications = @('All') }
        Locations = @{ IncludeLocations = @('All'); ExcludeLocations = @($location.Id) }
    }
    GrantControls = @{ Operator = 'OR'; BuiltInControls = @('block') }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

$params = @{
    DisplayName = 'CA-BASE-007-SessionControls'
    State       = 'enabledForReportingButNotEnforced'
    Conditions  = @{
        Users = @{ IncludeUsers = @('All') }
        Applications = @{ IncludeApplications = @('All') }
    }
    GrantControls = @{ Operator = 'OR'; BuiltInControls = @('mfa') }
    SessionControls = @{
        SignInFrequency   = @{ IsEnabled = $true; Type = 'hours'; Value = 12 }
        PersistentBrowser  = @{ IsEnabled = $true; Mode = 'never' }
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params

Import-Module Microsoft.Graph.Identity.SignIns

# Vervang door de daadwerkelijke break-glass-UPN('s)/groeps-id.
$breakGlassGroupId = '<object-id-van-break-glass-security-group>'

# Voeg de break-glass-groep toe aan de exclude-lijst van ELKE actieve policy — dit
# script toont het patroon per policy, in de praktijk over alle policies heen herhalen.
$policies = Get-MgIdentityConditionalAccessPolicy -All | Where-Object State -eq 'enabled'
foreach ($policy in $policies) {
    $excludeGroups = @($policy.Conditions.Users.ExcludeGroups) + $breakGlassGroupId | Select-Object -Unique
    Update-MgIdentityConditionalAccessPolicy -ConditionalAccessPolicyId $policy.Id -Conditions @{
        Users = @{ ExcludeGroups = $excludeGroups }
    }
}

# 1. Maak de gebruiksvoorwaarde aan in Entra:
#    Identity Governance > Terms of use > New terms
#    (PDF uploaden, taal instellen, 'Require users to expand the terms of use' aanzetten)
#
# 2. Koppel hem als grant control aan een policy die alle gebruikers raakt:
Import-Module Microsoft.Graph.Identity.SignIns

$termsOfUseId = '<object-id-van-de-terms-of-use>'   # zichtbaar in de URL van de agreement

$params = @{
    DisplayName = 'GLOBAL - 2140 - GRANT - Terms of Use'
    State       = 'enabledForReportingButNotEnforced'  # eerst report-only: een ToU die onverwacht blokkeert legt iedereen stil
    Conditions  = @{
        Users        = @{ IncludeUsers = @('All'); ExcludeGroups = @('<object-id-break-glass-groep>') }
        Applications = @{ IncludeApplications = @('All') }
    }
    GrantControls = @{
        Operator   = 'AND'
        TermsOfUse = @($termsOfUseId)
    }
}
New-MgIdentityConditionalAccessPolicy -BodyParameter $params
